/**
 * A planet's blocks drawn in the light their chunks carry — CODE-SPLIT.
 *
 * A REGISTERED CHUNK MANIFEST MODULE (MANIFEST_MODULES and ALLOWLIST in
 * tooling/check-shader-imports.mjs): the import site of `MaterialPluginBase`
 * for the blocks' light, loaded only by dynamic `import()` from the planet
 * view.
 *
 * A material plugin on every lit material named for a part of a chunk
 * (`ground`, `leaves`, `plants`, `water`), and on what the far tiles stand on
 * their ground (`standins`), which takes the sky's fill light as the ground does. A chunk's points carry, besides
 * the colour (the face's tint in the sky's light), their light sources'
 * light in the second of their second texture coordinates and their sky
 * light and corner shade in their third (blockLight.ts). The far terrain's
 * tiles wear materials of the same names but carry neither, and are drawn as
 * they are.
 *
 * In the fragments, the albedo (already in the sky's light) is darkened by
 * the corner shade at the world's strength; and the light sources' light,
 * where it is brighter than the sky's at this hour, is added as light the
 * face gives off, in the glow's colour, on the face's own colours (its
 * albedo over the sky's light). So at night the ground about a lava pool,
 * and the lava itself, stay lit, and nothing changes by day under the open
 * sky. Two attributes and a few sums: no texture, no pass.
 *
 * It also draws the sky's fill light turned and coloured (skyFill.ts), on
 * the chunks and on the far tiles, but not the water: the change from the
 * world's hemispheric light, given as three uniforms, added in the face's
 * colour by how the face is turned, and on a chunk's face by how open it is
 * to the sky. Without a change to draw it is not in the shader at all.
 *
 * As waterReflectChunk.ts does, the code is written in WGSL for WebGPU and
 * GLSL for WebGL2, chosen by the material's shader language, for both the
 * PBR material the chunks load with and the standard one. The two are kept
 * in step.
 */
import { ShaderLanguage } from '@babylonjs/core/Materials/shaderLanguage';
import { MaterialPluginBase } from '@babylonjs/core/Materials/materialPluginBase';
import type { UniformBuffer } from '@babylonjs/core/Materials/uniformBuffer';
import type { AbstractMesh } from '@babylonjs/core/Meshes/abstractMesh';
import type { BaseTexture } from '@babylonjs/core/Materials/Textures/baseTexture';
import type { Scene } from '@babylonjs/core/scene';
import type { BlockLightHandle, BlockLightState } from './blockLight';
import { SKY_OPEN, SKY_SHUT } from './skyFill';
import { RELIEF_APPLY_GLSL, RELIEF_APPLY_WGSL, RELIEF_GLSL, RELIEF_WGSL } from './blockRelief';
import { materialArrivals } from './materialArrivals';
import { isAway, takePlugin } from './awayMaterials';

/** Every input the blocks' light takes, in both languages. */
export const BLOCK_LIGHT_UNIFORMS = ['blockShading', 'blockGlow', 'blockGlowColor', 'blockDay', 'skyFillUp', 'skyFillSky', 'skyFillGround', 'blockRelief'] as const;

const UNIFORMS_GLSL = `#ifdef BLOCKLIGHT
uniform float blockShading;
uniform float blockGlow;
uniform vec3 blockGlowColor;
uniform float blockDay;
#endif
#ifdef SKYFILL
uniform vec3 skyFillUp;
uniform vec3 skyFillSky;
uniform vec3 skyFillGround;
#endif
#ifdef RELIEF
uniform float blockRelief;
#endif
`;

const UNIFORMS_WGSL = `#ifdef BLOCKLIGHT
uniform blockShading: f32;
uniform blockGlow: f32;
uniform blockGlowColor: vec3f;
uniform blockDay: f32;
#endif
#ifdef SKYFILL
uniform skyFillUp: vec3f;
uniform skyFillSky: vec3f;
uniform skyFillGround: vec3f;
#endif
#ifdef RELIEF
uniform blockRelief: f32;
#endif
`;

// The sky fill (skyFill.ts): the change a face turned up and one turned down take, between them by how the face
// is turned, in the face's colour, and on a chunk's face by how open it is to the sky, so a face the sky never
// reaches takes none. A far tile is open to the sky.
const SKY_FILL_GLSL = `#ifdef SKYFILL
vec3 skyFillOn(vec3 c, vec3 n, float sky) {
  vec3 light = mix(skyFillGround, skyFillSky, 0.5 + 0.5 * dot(n, skyFillUp));
  return c * light * smoothstep(${SKY_SHUT.toFixed(2)}, ${SKY_OPEN.toFixed(1)}, sky);
}
#endif
`;

const SKY_FILL_WGSL = `#ifdef SKYFILL
fn skyFillOn(c: vec3f, n: vec3f, sky: f32) -> vec3f {
  let light = mix(uniforms.skyFillGround, uniforms.skyFillSky, 0.5 + 0.5 * dot(n, uniforms.skyFillUp));
  return c * light * smoothstep(${SKY_SHUT.toFixed(2)}, ${SKY_OPEN.toFixed(1)}, sky);
}
#endif
`;

/** The sky fill added, `add` given the face's colour and its sky light: the chunk's, or all of it on a far tile. */
const skyFillAdd = (add: (sky: string) => string, light: string) => `#ifdef SKYFILL
#ifdef BLOCKLIGHT
${add(`${light}.y`)}
#else
${add('1.0')}
#endif
#endif
`;

/** The code for one language: its vertex parts, and its fragment parts for each material. */
export interface BlockLightCode {
  uniforms: string;
  vertexDefinitions: string;
  /** At the vertex's end: the light handed on to the fragments. */
  vertex: string;
  fragmentDefinitions: string;
  /** PBR, once its albedo is known: the shade on it, the glow found. */
  pbrAlbedo: string;
  /** PBR, before its colours are put together: the glow added to what it gives off. */
  pbrEmissive: string;
  /** Standard, once its diffuse colour is known: the shade on it, the glow found. */
  standardDiffuse: string;
  /** Standard, before the fog: the glow added. */
  standardEmissive: string;
}

// The light, x the light sources', y the sky's, z the corner shade. The sway (sway.ts) reads the plants' uv2.x
// and declares uv2 itself where it does.
const GLSL: BlockLightCode = {
  uniforms: UNIFORMS_GLSL,
  vertexDefinitions: `#ifdef BLOCKLIGHT
#if !defined(UV2) && !defined(SWAYWEIGHT)
attribute vec2 uv2;
#endif
#ifndef UV3
attribute vec2 uv3;
#endif
varying vec3 vBlockLight;
#endif
`,
  vertex: `#ifdef BLOCKLIGHT
vBlockLight = vec3(uv2.y, uv3.x, uv3.y);
#endif
`,
  fragmentDefinitions: `#ifdef BLOCKLIGHT
varying vec3 vBlockLight;
// The corner shade at the world's strength.
float blockShade() { return mix(1.0, vBlockLight.z, blockShading); }
// What the light sources give a face whose colour in the sky's light is c: its own colour, lit by how much
// brighter their light is than the sky's at this hour.
vec3 blockGlowOf(vec3 c) {
  return c / max(vBlockLight.y, 0.01) * blockGlowColor * (blockGlow * max(vBlockLight.x - vBlockLight.y * blockDay, 0.0));
}
#endif
${SKY_FILL_GLSL}${RELIEF_GLSL}`,
  pbrAlbedo: `${RELIEF_APPLY_GLSL}#ifdef BLOCKLIGHT
surfaceAlbedo *= blockShade();
vec3 blockGlowLight = blockGlowOf(surfaceAlbedo);
#endif
`,
  pbrEmissive: `#ifdef BLOCKLIGHT
finalEmissive += blockGlowLight;
#endif
${skyFillAdd((sky) => `finalEmissive += skyFillOn(surfaceAlbedo, normalW, ${sky});`, 'vBlockLight')}`,
  standardDiffuse: `#ifdef BLOCKLIGHT
baseColor.rgb *= blockShade();
vec3 blockGlowLight = blockGlowOf(baseColor.rgb);
#endif
`,
  standardEmissive: `#ifdef BLOCKLIGHT
color.rgb += blockGlowLight;
#endif
${skyFillAdd((sky) => `color.rgb += skyFillOn(baseColor.rgb, normalW, ${sky});`, 'vBlockLight')}`,
};

const WGSL: BlockLightCode = {
  uniforms: UNIFORMS_WGSL,
  vertexDefinitions: `#ifdef BLOCKLIGHT
#if !defined(UV2) && !defined(SWAYWEIGHT)
attribute uv2: vec2f;
#endif
#ifndef UV3
attribute uv3: vec2f;
#endif
varying vBlockLight: vec3f;
#endif
`,
  vertex: `#ifdef BLOCKLIGHT
vertexOutputs.vBlockLight = vec3f(vertexInputs.uv2.y, vertexInputs.uv3.x, vertexInputs.uv3.y);
#endif
`,
  fragmentDefinitions: `#ifdef BLOCKLIGHT
varying vBlockLight: vec3f;
fn blockShade(light: vec3f) -> f32 { return mix(1.0, light.z, uniforms.blockShading); }
fn blockGlowOf(c: vec3f, light: vec3f) -> vec3f {
  return c / max(light.y, 0.01) * uniforms.blockGlowColor * (uniforms.blockGlow * max(light.x - light.y * uniforms.blockDay, 0.0));
}
#endif
${SKY_FILL_WGSL}${RELIEF_WGSL}`,
  pbrAlbedo: `${RELIEF_APPLY_WGSL}#ifdef BLOCKLIGHT
surfaceAlbedo = surfaceAlbedo * blockShade(fragmentInputs.vBlockLight);
let blockGlowLight = blockGlowOf(surfaceAlbedo, fragmentInputs.vBlockLight);
#endif
`,
  pbrEmissive: `#ifdef BLOCKLIGHT
finalEmissive += blockGlowLight;
#endif
${skyFillAdd((sky) => `finalEmissive += skyFillOn(surfaceAlbedo, normalW, ${sky});`, 'fragmentInputs.vBlockLight')}`,
  standardDiffuse: `#ifdef BLOCKLIGHT
baseColor = vec4f(baseColor.rgb * blockShade(fragmentInputs.vBlockLight), baseColor.a);
let blockGlowLight = blockGlowOf(baseColor.rgb, fragmentInputs.vBlockLight);
#endif
`,
  standardEmissive: `#ifdef BLOCKLIGHT
color = vec4f(color.rgb + blockGlowLight, color.a);
#endif
${skyFillAdd((sky) => `color = vec4f(color.rgb + skyFillOn(baseColor.rgb, normalW, ${sky}), color.a);`, 'fragmentInputs.vBlockLight')}`,
};

/** The blocks' light code for a material: WGSL on WebGPU, GLSL elsewhere. */
export function selectBlockLightCode(engineKind?: string): BlockLightCode {
  return engineKind === 'webgpu' ? WGSL : GLSL;
}

const PLUGIN_NAME = 'BlockLight';
/** The parts of a chunk, and what the far tiles stand on their ground, by their materials' names. */
const PARTS = new Set(['ground', 'leaves', 'plants', 'water', 'standins']);
/** The parts drawn with relief: solid faces, not the water or the plants' crossed pictures. */
const RELIEF_PARTS = new Set(['ground', 'leaves']);

/** A chunk material's textures, as far as the maps go: glTF's normalTexture is the bump, its metallic-roughness the metallic. */
type Mapped = { bumpTexture: BaseTexture | null; metallicTexture?: BaseTexture | null };

class BlockLightPlugin extends MaterialPluginBase {
  private _isEnabled = true;
  /** The chunk's normal atlas, taken from the material so it draws no normal map of its own as well; the relief reads it. */
  private normals: BaseTexture | null = null;
  /** The chunk's shine (roughness) atlas, which the material keeps while the world asks for relief. */
  private shine: BaseTexture | null = null;

  constructor(
    material: ConstructorParameters<typeof MaterialPluginBase>[0],
    private state: { now: BlockLightState | null },
  ) {
    super(material, PLUGIN_NAME, 330, { BLOCKLIGHT: false, SKYFILL: false, RELIEF: false, BLOCKMAPS: false }, true, true);
    this.takeMaps();
  }

  /** The material's normal and shine maps, where a chunk's ground or leaves carry them. */
  private takeMaps(): void {
    if (!this._isEnabled || !this.pbr || !RELIEF_PARTS.has(this._material.name)) return;
    const m = this._material as unknown as Mapped;
    if (m.bumpTexture) {
      this.normals = m.bumpTexture;
      m.bumpTexture = null;
    }
    if (m.metallicTexture && !this.shine) this.shine = m.metallicTexture;
    this.showShine((this.state.now?.relief ?? 0) > 0);
  }

  /** The shine drawn while the world asks for relief, and none (fully rough, as before maps) at none. */
  showShine(on: boolean): void {
    if (!this.shine) return;
    const m = this._material as unknown as Mapped;
    const want = on && this._isEnabled ? this.shine : null;
    if (m.metallicTexture !== want) m.metallicTexture = want;
  }

  /** Draws from another planet's state from now on (awayMaterials.ts). */
  rebind(state: { now: BlockLightState | null }): void {
    this.state = state;
  }

  private get pbr(): boolean {
    return this._material.getClassName() === 'PBRMaterial';
  }

  get isEnabled(): boolean {
    return this._isEnabled;
  }

  set isEnabled(value: boolean) {
    if (this._isEnabled === value) return;
    this._isEnabled = value;
    // Given back as baked: the material draws its own maps again.
    if (!value) {
      const m = this._material as unknown as Mapped;
      if (this.normals) m.bumpTexture = this.normals;
      if (this.shine) m.metallicTexture = this.shine;
      this.normals = null;
      this.shine = null;
    } else this.takeMaps();
    this.markAllDefinesAsDirty();
    this._enable(value);
  }

  override getClassName(): string {
    return 'BlockLightPlugin';
  }

  override isCompatible(shaderLanguage: ShaderLanguage): boolean {
    return shaderLanguage === ShaderLanguage.GLSL || shaderLanguage === ShaderLanguage.WGSL;
  }

  /** Whether this mesh's points carry their light: a chunk's do, a far tile's do not. */
  private lit(mesh: AbstractMesh | undefined): boolean {
    return mesh !== undefined && mesh.isVerticesDataPresent('uv2') && mesh.isVerticesDataPresent('uv3');
  }

  override prepareDefines(defines: Parameters<MaterialPluginBase['prepareDefines']>[0], _scene: Scene, mesh: AbstractMesh): void {
    const d = defines as unknown as Record<string, boolean>;
    d['BLOCKLIGHT'] = this._isEnabled && this.lit(mesh);
    // The sky fill on the ground, leaves and plants, near and far, while there is a change to draw; not on the water.
    d['SKYFILL'] = this._isEnabled && !this.skyFillHeld && !!this.state.now?.fill && this._material.name !== 'water';
    // The relief (blockRelief.ts) on a chunk's ground and leaves drawn from the atlas, while the world asks for it.
    d['RELIEF'] = d['BLOCKLIGHT'] && this.pbr && RELIEF_PARTS.has(this._material.name) && !!(this._material as unknown as { albedoTexture?: unknown }).albedoTexture && (this.state.now?.relief ?? 0) > 0;
    // The blocks' real normal maps, where the chunk carries them.
    this.takeMaps();
    d['BLOCKMAPS'] = d['RELIEF'] && this.normals !== null;
  }

  override getSamplers(samplers: string[]): void {
    samplers.push('blockNormalSampler');
  }

  override getActiveTextures(activeTextures: BaseTexture[]): void {
    if (this.normals) activeTextures.push(this.normals);
  }

  override hasTexture(texture: BaseTexture): boolean {
    return texture === this.normals;
  }

  override isReadyForSubMesh(): boolean {
    return !this.normals || this.normals.isReady();
  }

  /** The sky fill or the relief came or went: the shader changes with it. */
  fillChanged(): void {
    this.markAllDefinesAsDirty();
  }

  /** Held off by the GPU profile (src/debug/gpuProfile.ts), so it can time the sky fill alone. */
  get skyFillHeld(): boolean {
    return this._skyFillHeld;
  }

  set skyFillHeld(value: boolean) {
    if (this._skyFillHeld === value) return;
    this._skyFillHeld = value;
    this.markAllDefinesAsDirty();
  }

  private _skyFillHeld = false;

  override getAttributes(attributes: string[], _scene: Scene, mesh: AbstractMesh): void {
    if (!this._isEnabled || !this.lit(mesh)) return;
    for (const a of ['uv2', 'uv3']) if (!attributes.includes(a)) attributes.push(a);
  }

  override getUniforms(shaderLanguage: ShaderLanguage = ShaderLanguage.GLSL) {
    const code = shaderLanguage === ShaderLanguage.WGSL ? UNIFORMS_WGSL : UNIFORMS_GLSL;
    return {
      ubo: [
        { name: 'blockShading', size: 1, type: 'float' },
        { name: 'blockGlow', size: 1, type: 'float' },
        { name: 'blockGlowColor', size: 3, type: 'vec3' },
        { name: 'blockDay', size: 1, type: 'float' },
        { name: 'skyFillUp', size: 3, type: 'vec3' },
        { name: 'skyFillSky', size: 3, type: 'vec3' },
        { name: 'skyFillGround', size: 3, type: 'vec3' },
        { name: 'blockRelief', size: 1, type: 'float' },
      ],
      vertex: code,
      fragment: code,
    };
  }

  override bindForSubMesh(ubo: UniformBuffer): void {
    if (!this._isEnabled) return;
    const s = this.state.now;
    // Until the first frame: the shade as baked, and no glow.
    ubo.updateFloat('blockShading', s ? s.shading : 1);
    ubo.updateFloat('blockGlow', s ? s.glow : 0);
    const c = s?.color ?? [1, 1, 1];
    ubo.updateFloat3('blockGlowColor', c[0], c[1], c[2]);
    ubo.updateFloat('blockDay', s ? s.day : 1);
    ubo.updateFloat('blockRelief', s?.relief ?? 0);
    if (this.normals && (s?.relief ?? 0) > 0) ubo.setTexture('blockNormalSampler', this.normals);
    const f = s?.fill;
    if (f) {
      ubo.updateFloat3('skyFillUp', f.up[0], f.up[1], f.up[2]);
      ubo.updateFloat3('skyFillSky', f.sky[0], f.sky[1], f.sky[2]);
      ubo.updateFloat3('skyFillGround', f.ground[0], f.ground[1], f.ground[2]);
    }
  }

  override getCustomCode(shaderType: string, shaderLanguage: ShaderLanguage = ShaderLanguage.GLSL): { [pointName: string]: string } | null {
    const code = selectBlockLightCode(shaderLanguage === ShaderLanguage.WGSL ? 'webgpu' : 'webgl2');
    if (shaderType === 'vertex') return { CUSTOM_VERTEX_DEFINITIONS: code.vertexDefinitions, CUSTOM_VERTEX_MAIN_END: code.vertex };
    if (this.pbr) return { CUSTOM_FRAGMENT_DEFINITIONS: code.fragmentDefinitions, CUSTOM_FRAGMENT_UPDATE_ALPHA: code.pbrAlbedo, CUSTOM_FRAGMENT_BEFORE_FINALCOLORCOMPOSITION: code.pbrEmissive };
    return { CUSTOM_FRAGMENT_DEFINITIONS: code.fragmentDefinitions, CUSTOM_FRAGMENT_UPDATE_DIFFUSE: code.standardDiffuse, CUSTOM_FRAGMENT_BEFORE_FOG: code.standardEmissive };
  }
}

/** What the blocks' light goes on: lit materials named for a part of a chunk. */
const takes = (m: Scene['materials'][number]): boolean => {
  if (!PARTS.has(m.name)) return false;
  const kind = m.getClassName();
  return kind === 'StandardMaterial' || kind === 'PBRMaterial';
};

/**
 * Draw every chunk part's material in the scene in its light, and each one
 * that arrives (from the next `update`). `dispose` gives them back as baked
 * and adds it to no more.
 */
export function createBlockLightOn(scene: Scene, _opts: { engineKind?: string }): BlockLightHandle {
  const shared: { now: BlockLightState | null } = { now: null };
  const plugins: BlockLightPlugin[] = [];
  // Every material in the scene, and each one as it arrives.
  const arrivals = materialArrivals(scene);
  const attachAll = () =>
    arrivals.take((m) => {
      if (takes(m) && isAway(m)) return false;
      const p = takes(m) ? takePlugin(m, PLUGIN_NAME, shared, () => new BlockLightPlugin(m, shared)) : undefined;
      if (p) plugins.push(p);
    });
  attachAll();
  let stopped = false;
  return {
    update(s) {
      if (stopped) return;
      attachAll();
      const filled = !!shared.now?.fill;
      const raised = (shared.now?.relief ?? 0) > 0;
      shared.now = s;
      if (!!s.fill !== filled || (s.relief ?? 0) > 0 !== raised) for (const p of plugins) p.fillChanged();
      if ((s.relief ?? 0) > 0 !== raised) for (const p of plugins) p.showShine((s.relief ?? 0) > 0);
    },
    dispose() {
      stopped = true;
      arrivals.dispose();
      for (const p of plugins) p.isEnabled = false;
      plugins.length = 0;
    },
  };
}
